<script setup>
import { computed, onMounted, ref } from 'vue';
import { storeToRefs } from 'pinia';
import WCard from '@/components/common/WCard.vue';
import WButton from '@/components/common/WButton.vue';
import { usePianoSmartStore } from '@/stores/pianoSmart.store';
import { useToastStore } from '@/stores/toast.store';

const store = usePianoSmartStore();
const toast = useToastStore();
const { state, input, readiness, preview, recommendedAllocations, finalAllocations, plans, selectedPlan, error, capitalToAllocate, allocationDifference, canSave } = storeToRefs(store);
const tab = ref('create'); const step = ref(1); const showInfo = ref(false); const detail = ref(false);
const sources = ['Stipendio', 'Bonus', 'Regalo', 'Rimborso', 'Vendita', 'Entrata occasionale', 'Altro'];
const categories = computed(() => preview.value?.allocations || []);
const questions = computed(() => readiness.value?.questions || []);
const amountValid = computed(() => Number.isFinite(Number(input.value.amount)) && Number(input.value.amount) > 0);
const displayAmount = (value) => new Intl.NumberFormat('it-IT', { style: 'currency', currency: 'EUR' }).format(Number(value || 0));
const label = (item) => item.label || item.name || item.category;
const amount = (item) => item.finalAmount ?? item.amount ?? item.recommendedAmount ?? 0;
const updateFinal = (item, value) => { const target = finalAllocations.value.find((candidate) => (candidate.category || candidate.label) === (item.category || item.label)); if (target) target.finalAmount = value; };
const continueAmount = async () => { if (!amountValid.value) return; if (!readiness.value) await store.loadReadiness(); step.value = questions.value.length ? 2 : 3; };
const generate = async () => { await store.generatePreview(); if (state.value === 'previewReady') step.value = 3; };
const save = async () => { const result = await store.savePlan(); if (result) { toast.success('Piano Smart salvato.'); tab.value = 'history'; await store.loadPlans(); } };
const openHistory = async () => { tab.value = 'history'; await store.loadPlans(); };
const openDetail = async (id) => { await store.loadPlan(id); detail.value = true; };
const status = async (value) => { if (selectedPlan.value?.id) { await store.updateStatus(selectedPlan.value.id, value); detail.value = false; } };
onMounted(() => { if (tab.value === 'history') store.loadPlans(); });
</script>

<template>
  <div class="piano-view">
    <header class="page-header">
      <div><h1 class="page-title">Piano Smart</h1><p class="page-sub">Trasforma una nuova entrata in un piano costruito sulla tua situazione finanziaria.</p></div>
      <button class="info-link" type="button" @click="showInfo = true">Come funziona?</button>
    </header>
    <div class="tabs" role="tablist">
      <button type="button" :class="{ active: tab === 'create' }" @click="tab = 'create'">Crea piano</button>
      <button type="button" :class="{ active: tab === 'history' }" @click="openHistory">I miei piani</button>
    </div>

    <template v-if="tab === 'create'">
      <div class="steps" aria-label="Avanzamento piano"><span :class="{ active: step >= 1 }">1 Importo</span><span :class="{ active: step >= 2 }">2 Contesto</span><span :class="{ active: step >= 3 }">3 Il tuo Piano</span></div>
      <WCard v-if="step === 1" class="flow-card">
        <h2>Quanto vuoi organizzare?</h2><p class="muted">Inserisci la nuova somma che vuoi distribuire.</p>
        <label for="smart-amount">Importo</label><div class="amount-input"><span>€</span><input id="smart-amount" v-model="input.amount" inputmode="decimal" type="number" min="0" step="0.01" placeholder="0,00" :aria-invalid="!amountValid && input.amount !== ''" /></div>
        <p v-if="input.amount !== '' && !amountValid" class="field-error" role="alert">Inserisci un importo maggiore di zero.</p>
        <label for="smart-source">Da dove arriva questa somma?</label><select id="smart-source" v-model="input.sourceType"><option value="">Seleziona</option><option v-for="source in sources" :key="source" :value="source">{{ source }}</option></select>
        <fieldset><legend>Questa entrata si ripeterà?</legend><div class="choice-row"><label v-for="choice in [{ value: true, text: 'Sì' }, { value: false, text: 'No' }, { value: null, text: 'Non lo so' }]" :key="choice.text"><input v-model="input.recurring" type="radio" name="smart-recurring" :value="choice.value" /> {{ choice.text }}</label></div></fieldset>
        <label for="smart-expenses">Spese obbligatorie da coprire con questa somma</label><input id="smart-expenses" v-model="input.mandatoryExpenses" type="number" min="0" step="0.01" />
        <p class="capital">Capitale da organizzare: <strong>{{ displayAmount(capitalToAllocate) }}</strong></p>
        <WButton variant="primary" size="lg" :disabled="!amountValid" @click="continueAmount">Continua</WButton>
      </WCard>

      <WCard v-else-if="step === 2" class="flow-card"><h2>Completiamo il contesto</h2><p class="muted">WALLT ha bisogno solo delle informazioni che non conosce ancora.</p><div v-if="state === 'contextLoading'" class="loading" role="status">Analizzo la tua situazione…</div><div v-else><div v-for="question in questions" :key="question.id" class="question"><label :for="`question-${question.id}`">{{ question.label || question.question }}</label><select v-if="question.type === 'select' || question.type === 'yes/no'" :id="`question-${question.id}`" v-model="input.manualContextAnswers[question.id]"><option value="">Seleziona</option><option v-for="option in question.options || (question.type === 'yes/no' ? ['Sì', 'No'] : [])" :key="option" :value="option">{{ option }}</option></select><input v-else :id="`question-${question.id}`" v-model="input.manualContextAnswers[question.id]" :type="question.type === 'number' || question.type === 'currency' ? 'number' : 'text'" /></div><WButton variant="primary" size="lg" :loading="state === 'generating'" @click="generate">Crea il mio piano</WButton></div></WCard>

      <section v-else class="result"><WCard v-if="state === 'generating' || state === 'contextLoading'" class="loading" role="status">Sto costruendo il tuo Piano Smart…</WCard><WCard v-else-if="error" class="error" role="alert">{{ error.message }} <WButton variant="secondary" size="sm" @click="store.reset">Ricomincia</WButton></WCard><template v-else-if="preview"><WCard class="hero"><p>Il tuo Piano Smart</p><strong>{{ displayAmount(preview.incomingAmount || input.amount) }}</strong><span>da organizzare</span><div class="hero-meta"><span>{{ displayAmount(preview.mandatoryExpenses || input.mandatoryExpenses) }} spese immediate</span><span>{{ displayAmount(preview.allocatableCapital ?? capitalToAllocate) }} capitale allocato</span></div></WCard><WCard class="allocations"><h2>Come distribuire la somma</h2><div class="bar" aria-label="Distribuzione del capitale"><i v-for="item in categories" :key="item.category" :style="{ width: `${Math.max(Number(item.recommendedPercentage || 0), 0)}%` }" /></div><div v-for="(item, index) in finalAllocations" :key="item.category || index" class="allocation"><div><strong>{{ label(item) }}</strong><p>{{ item.explanation || item.reason || 'Quota del piano personalizzabile.' }}</p><small>{{ item.recommendedPercentage || 0 }}% · WALLT: {{ displayAmount(item.recommendedAmount) }}</small></div><label><span class="sr-only">Importo {{ label(item) }}</span><input :value="amount(item)" type="number" min="0" step="0.01" @input="updateFinal(item, $event.target.value)" /></label></div><p class="difference" :class="{ invalid: allocationDifference !== 0 }">{{ allocationDifference > 0 ? `Ancora da distribuire: ${displayAmount(allocationDifference)}` : allocationDifference < 0 ? `Hai superato il totale di ${displayAmount(Math.abs(allocationDifference))}` : 'Totale distribuito' }}</p><div class="actions"><WButton variant="secondary" @click="store.resetFinalAllocations">Ripristina suggerimento WALLT</WButton><WButton variant="primary" :disabled="!canSave" :loading="state === 'saving'" @click="save">Salva Piano Smart</WButton></div></WCard><WCard v-if="preview.reasons?.length || preview.explanations?.length" class="text-card"><h2>Perché WALLT ti propone questa distribuzione?</h2><ul><li v-for="reason in (preview.reasons || preview.explanations)" :key="reason">{{ reason.text || reason }}</li></ul></WCard><WCard v-if="preview.contextSummary" class="text-card"><details><summary>Dati utilizzati per questo piano</summary><p>{{ preview.contextSummary }}</p></details></WCard></template></section>
    </template>

    <section v-else class="history"><WCard v-if="!plans.length" class="empty"><h2>Non hai ancora creato un Piano Smart.</h2><WButton variant="primary" @click="tab = 'create'">Crea il tuo primo piano</WButton></WCard><WCard v-for="plan in plans" :key="plan.id" class="history-item" hoverable @click="openDetail(plan.id)"><strong>{{ plan.sourceType || 'Entrata' }} — {{ displayAmount(plan.incomingAmount || plan.amount) }}</strong><span>{{ plan.status || 'Attivo' }}</span></WCard></section>
    <div v-if="showInfo" class="modal-backdrop" @click.self="showInfo = false"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="smart-info-title"><button class="close" type="button" aria-label="Chiudi" @click="showInfo = false">×</button><h2 id="smart-info-title">Come funziona?</h2><p>WALLT utilizza i dati che hai già inserito per proporti una suddivisione personalizzata. Puoi modificarla prima di salvarla.</p><p>Il Piano Smart non sposta denaro automaticamente: le decisioni finali restano sempre all'utente.</p></div></div>
    <div v-if="detail && selectedPlan" class="modal-backdrop" @click.self="detail = false"><div class="modal" role="dialog" aria-modal="true"><button class="close" type="button" aria-label="Chiudi" @click="detail = false">×</button><h2>Dettaglio Piano Smart</h2><p>Capitale iniziale: <strong>{{ displayAmount(selectedPlan.incomingAmount || selectedPlan.amount) }}</strong></p><p>Stato: {{ selectedPlan.status || 'Attivo' }}</p><WButton variant="secondary" @click="status('completato')">Completa</WButton><WButton variant="secondary" @click="status('archiviato')">Archivia</WButton></div></div>
  </div>
</template>

<style scoped>
.piano-view { max-width: 820px; margin: 0 auto; padding-bottom: 2rem; } .page-header { display:flex; justify-content:space-between; gap:1rem; align-items:flex-start; margin-bottom:1.25rem; } .page-title { font-size:1.5rem; font-weight:700; color:var(--text-primary); } .page-sub,.muted { color:var(--text-secondary); line-height:1.55; font-size:.875rem; } .info-link { color:var(--accent-text); background:none; border:0; padding:.5rem 0; cursor:pointer; font:inherit; font-weight:600; } .tabs { display:flex; gap:.4rem; border-bottom:1px solid var(--divider); margin-bottom:1.25rem; } .tabs button { border:0; background:none; padding:.75rem 1rem; color:var(--text-muted); font:inherit; cursor:pointer; border-bottom:2px solid transparent; } .tabs button.active { color:var(--accent-text); border-color:var(--accent-green); font-weight:700; } .steps { display:flex; gap:.5rem; margin-bottom:1rem; color:var(--text-muted); font-size:.75rem; } .steps span { flex:1; padding:.5rem; text-align:center; border-bottom:2px solid var(--border); } .steps span.active { color:var(--text-primary); border-color:var(--accent-green); } .flow-card,.allocations,.hero,.text-card,.empty { display:flex; flex-direction:column; gap:.9rem; margin-bottom:1rem; } h2 { color:var(--text-primary); font-size:1.1rem; } label,legend { color:var(--text-primary); font-size:.875rem; font-weight:600; } input,select { width:100%; min-height:44px; border:1px solid var(--border); border-radius:var(--radius-md); padding:.65rem .75rem; background:var(--surface-subtle); color:var(--text-primary); font:inherit; } .amount-input { display:flex; align-items:center; gap:.35rem; font-size:1.5rem; font-weight:700; } .amount-input input { font-size:1.5rem; font-weight:700; } fieldset { border:0; padding:0; } .choice-row { display:flex; flex-wrap:wrap; gap:.75rem; } .choice-row label { display:flex; align-items:center; gap:.35rem; font-weight:400; } .choice-row input { width:auto; min-height:auto; } .capital,.difference { color:var(--text-secondary); } .capital strong { color:var(--text-primary); } .field-error,.difference.invalid { color:var(--negative); } .loading,.error { padding:1.5rem; text-align:center; color:var(--text-secondary); } .hero { align-items:center; text-align:center; } .hero p,.hero span { color:var(--text-secondary); margin:0; } .hero strong { font-size:2.4rem; color:var(--text-primary); } .hero-meta { display:flex; gap:1rem; flex-wrap:wrap; justify-content:center; font-size:.8rem; } .bar { display:flex; height:1rem; overflow:hidden; border-radius:999px; background:var(--surface-subtle); } .bar i { background:var(--accent-green); border-right:2px solid var(--surface); } .allocation { display:grid; grid-template-columns:1fr 10rem; gap:1rem; align-items:center; padding:.85rem 0; border-top:1px solid var(--divider); } .allocation p { margin:.25rem 0; color:var(--text-secondary); font-size:.8rem; } .allocation small { color:var(--text-muted); } .actions { display:flex; flex-wrap:wrap; gap:.75rem; } .actions > * { flex:1; } .text-card ul { margin:0; padding-left:1.2rem; color:var(--text-secondary); line-height:1.6; } .history-item { display:flex; justify-content:space-between; margin-bottom:.75rem; cursor:pointer; color:var(--text-primary); } .history-item span { color:var(--text-secondary); } .modal-backdrop { position:fixed; inset:0; z-index:20; display:grid; place-items:center; padding:1rem; background:rgba(0,0,0,.45); } .modal { position:relative; max-width: thirtyrem; width:100%; padding:1.5rem; border-radius:var(--radius-xl); background:var(--surface); color:var(--text-secondary); box-shadow:var(--shadow-lg); } .close { position:absolute; top:.5rem; right:.75rem; border:0; background:none; color:var(--text-primary); font-size:1.5rem; cursor:pointer; } .sr-only { position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0,0,0,0); } @media(max-width:600px){ .page-header{display:block}.info-link{padding-left:0}.allocation{grid-template-columns:1fr 7rem}.actions{flex-direction:column} }
</style>
